// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;
    function setUp() public {
        c = new C();
        originalOwner = c.owner();
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != originalOwner);
        vm.assume(newOwner != originalOwner);
        vm.prank(caller);
        bool success = c.setOwner(newOwner);
        assertTrue(c.owner() == originalOwner && success);
    }
}
